/**
 * Server-owned catalog of ten coin packs. Coins are 1:1 with rupees and
every pack is worth ten bets at its matching chip denomination
(`coins = chipValue * 10`). Clients select a `sku` — they never send a
price; the server prices the SKU from this catalog and rejects any
deposit whose amount does not match.

 * @summary List the coin packs on sale for one game's wallet
 */
export const getListCoinPacksUrl = (params?: ListCoinPacksParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/payments/coin-packs?${stringifiedParams}`
    : `/api/payments/coin-packs`;
};

export const listCoinPacks = async (
  params?: ListCoinPacksParams,
  options?: RequestInit,
): Promise<CoinPack[]> => {
  return customFetch<CoinPack[]>(getListCoinPacksUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListCoinPacksQueryKey = (params?: ListCoinPacksParams) => {
  return [`/api/payments/coin-packs`, ...(params ? [params] : [])] as const;
};

